import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '../context/AuthContext';
import axios from 'axios';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

const SAMPLE_QUIZZES = [
  { id: 'geo', title: '🌍 World Geography', category: 'Geography', difficulty: 'Medium', questions: 5, color: '#00d4ff' },
  { id: 'tech', title: '💻 Tech & Science', category: 'Technology', difficulty: 'Hard', questions: 5, color: '#9b59ff' },
  { id: 'pop', title: '🎬 Pop Culture', category: 'Entertainment', difficulty: 'Easy', questions: 5, color: '#ff3cac' },
  { id: 'custom', title: '➕ Create Custom', category: 'Custom', difficulty: '—', questions: '?', color: '#ff8c42' },
];

export default function DashboardPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [joinCode, setJoinCode] = useState('');
  const [creating, setCreating] = useState(false);
  const [modal, setModal] = useState(false);
  const [selectedQuiz, setSelectedQuiz] = useState(null);
  const [error, setError] = useState('');

  const handleCreateRoom = async () => {
    setError('');
    setCreating(true);
    try {
      const res = await axios.post(`${API}/rooms/create`, { quizId: null });
      navigate(`/lobby/${res.data.code}`);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to create room');
    } finally {
      setCreating(false);
    }
  };

  const handleJoin = (e) => {
    e.preventDefault();
    if (!joinCode.trim()) return;
    navigate(`/lobby/${joinCode.toUpperCase()}`);
  };

  const statCards = [
    { label: 'Games Played', value: user?.stats?.gamesPlayed || 0, icon: '🎮', color: '#00d4ff' },
    { label: 'Games Won', value: user?.stats?.gamesWon || 0, icon: '🏆', color: '#ffd700' },
    { label: 'Total Score', value: (user?.stats?.totalScore || 0).toLocaleString(), icon: '⭐', color: '#9b59ff' },
    { label: 'Correct Answers', value: user?.stats?.correctAnswers || 0, icon: '✅', color: '#00ff88' },
  ];

  return (
    <div style={{ minHeight: '100vh', paddingTop: '100px', padding: '100px 24px 60px' }}>
      <div className="container">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          style={{ marginBottom: 48 }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginBottom: 8 }}>
            <div style={{
              width: 56, height: 56, borderRadius: 16,
              background: 'var(--bg-card)', border: '1px solid var(--border)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: '1.8rem',
            }}>{user?.avatar}</div>
            <div>
              <h1 style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: '2rem', color: 'var(--text-primary)' }}>
                Welcome, <span className="gradient-text">{user?.username}</span>!
              </h1>
              <p style={{ color: 'var(--text-secondary)' }}>Ready to battle?</p>
            </div>
          </div>
        </motion.div>

        {/* Stats */}
        <motion.div
          style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: 16, marginBottom: 48 }}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.2 }}
        >
          {statCards.map((s, i) => (
            <motion.div
              key={i}
              className="glass-card"
              style={{ padding: '24px' }}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.08 }}
              whileHover={{ y: -4, scale: 1.02 }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 12 }}>
                <div style={{
                  width: 40, height: 40, borderRadius: 12,
                  background: `${s.color}20`,
                  border: `1px solid ${s.color}30`,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: '1.2rem',
                }}>{s.icon}</div>
                <span style={{ color: 'var(--text-muted)', fontSize: '0.8rem', fontWeight: 500, textTransform: 'uppercase', letterSpacing: '0.05em' }}>{s.label}</span>
              </div>
              <div style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: '2rem', color: s.color }}>{s.value}</div>
            </motion.div>
          ))}
        </motion.div>

        {user?.role === 'admin' && (
          <motion.div
            className="glass-card neon-border-purple"
            style={{ padding: 20, marginBottom: 24, display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 12 }}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
          >
            <div>
              <h3 style={{ fontFamily: 'var(--font-display)', marginBottom: 6 }}>Admin Tools</h3>
              <p style={{ color: 'var(--text-secondary)', fontSize: '0.9rem' }}>Create and manage quiz content.</p>
            </div>
            <button className="btn btn-primary" onClick={() => navigate('/admin/quizzes/new')}>
              ➕ Add New Quiz
            </button>
          </motion.div>
        )}

        {/* Actions Grid */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(340px, 1fr))', gap: 24, marginBottom: 48 }}>
          {/* Create Room */}
          <motion.div
            className="glass-card neon-border-blue"
            style={{ padding: 32 }}
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.3 }}
          >
            <h2 style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: '1.4rem', marginBottom: 8, color: 'var(--text-primary)' }}>
              🚀 Create a Room
            </h2>
            <p style={{ color: 'var(--text-secondary)', marginBottom: 24, lineHeight: 1.6 }}>
              Set up a new game room, pick a quiz, and invite friends with a shareable code.
            </p>
            {error && <p style={{ color: '#ff6b6b', marginBottom: 12, fontSize: '0.88rem' }}>⚠️ {error}</p>}
            <motion.button
              className="btn btn-primary btn-lg btn-glow"
              style={{ width: '100%' }}
              onClick={handleCreateRoom}
              disabled={creating}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              {creating ? (
                <span style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  <div className="spinner" style={{ width: 18, height: 18, borderWidth: 2 }} /> Creating...
                </span>
              ) : '⚡ Create Room'}
            </motion.button>
          </motion.div>

          {/* Join Room */}
          <motion.div
            className="glass-card neon-border-purple"
            style={{ padding: 32 }}
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.4 }}
          >
            <h2 style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: '1.4rem', marginBottom: 8, color: 'var(--text-primary)' }}>
              🎮 Join a Room
            </h2>
            <p style={{ color: 'var(--text-secondary)', marginBottom: 24, lineHeight: 1.6 }}>
              Got an invite? Enter the 6-character room code to jump right into the game.
            </p>
            <form onSubmit={handleJoin} style={{ display: 'flex', gap: 10 }}>
              <input
                className="input-field"
                style={{ flex: 1, letterSpacing: '0.2em', textTransform: 'uppercase', fontWeight: 700, textAlign: 'center' }}
                placeholder="ABC123"
                value={joinCode}
                onChange={e => setJoinCode(e.target.value.toUpperCase())}
                maxLength={6}
              />
              <motion.button
                type="submit"
                className="btn btn-primary"
                disabled={joinCode.length < 6}
                whileHover={{ scale: 1.04 }}
                whileTap={{ scale: 0.97 }}
              >
                Join →
              </motion.button>
            </form>
          </motion.div>
        </div>

        {/* Quiz Selection */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.5 }}
        >
          <h2 style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: '1.6rem', marginBottom: 24, color: 'var(--text-primary)' }}>
            🎯 Featured Quizzes
          </h2>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(240px, 1fr))', gap: 16 }}>
            {SAMPLE_QUIZZES.map((quiz, i) => (
              <motion.div
                key={quiz.id}
                className="glass-card glass-hover"
                style={{ padding: 24, cursor: 'pointer', position: 'relative', overflow: 'hidden' }}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.5 + i * 0.08 }}
                whileHover={{ y: -6 }}
                onClick={handleCreateRoom}
              >
                <div style={{
                  position: 'absolute', top: 0, right: 0,
                  width: 120, height: 120, borderRadius: '0 0 0 120px',
                  background: `radial-gradient(circle, ${quiz.color}20 0%, transparent 70%)`,
                }} />
                <div style={{ marginBottom: 16, fontSize: '2rem' }}>{quiz.title.split(' ')[0]}</div>
                <h3 style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: '1rem', marginBottom: 8, color: 'var(--text-primary)' }}>
                  {quiz.title.slice(3)}
                </h3>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                  <span className={`badge badge-${i === 0 ? 'blue' : i === 1 ? 'purple' : i === 2 ? 'pink' : 'orange'}`}>
                    {quiz.category}
                  </span>
                  <span className="badge" style={{ background: 'rgba(255,255,255,0.05)', color: 'var(--text-muted)', border: '1px solid var(--border)' }}>
                    {quiz.questions} Qs
                  </span>
                </div>
                <div style={{
                  marginTop: 16, fontSize: '0.8rem',
                  color: quiz.difficulty === 'Easy' ? '#00ff88' : quiz.difficulty === 'Hard' ? '#ff3cac' : '#00d4ff',
                  fontWeight: 600,
                }}>
                  {quiz.difficulty !== '—' && `● ${quiz.difficulty}`}
                </div>
              </motion.div>
            ))}
          </div>
        </motion.div>
      </div>
    </div>
  );
}
